"""Sequential batch job runner preserving Meridian CRM 4.2 error semantics."""

from typing import Callable


def run_jobs(jobs: list[dict], executor: Callable[[dict], object]) -> list[dict]:
    """Run jobs sequentially and return one log entry per attempted job."""
    run_log: list[dict] = []

    for job in jobs:
        policy = job["on_error"]["policy"]
        retry_count = job["on_error"]["retries"] if policy == "RETRY" else 0
        attempts = 0

        while True:
            attempts += 1

            try:
                executor(job)
            except Exception:
                if policy == "CONTINUE":
                    run_log.append(
                        {
                            "name": job["name"],
                            "attempts": attempts,
                            "outcome": "skip",
                            "audits": ["BATCH_ROWSKIP"],
                        }
                    )
                    break

                if policy == "RETRY" and attempts <= retry_count:
                    continue

                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "abort",
                        "audits": [],
                    }
                )
                return run_log
            else:
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "ok",
                        "audits": [],
                    }
                )
                break

    return run_log
